extern "C" int strlen(const char *);

class string_buf
{
public:
  void *data;
  int ref_count;
  int char_length;

  int compare(const char *str) const
  {
    int i;
    const char *a = reinterpret_cast<const char *>(data);
    for (i = 0; i < char_length; i++) {
      if (str[i] == '\0') return -1;
      if (a[i] == str[i]) continue;
      if (str[i] > a[i]) return 1;
      if (str[i] < a[i]) return -1;
    }
    if (str[i] == '\0') return 0;
    return 1;
  }

  bool is_equal(const char *str) const
  {
    return (compare(str) == 0);
  }
};

class stringx
{
  friend stringx operator+(const stringx& lhs, const char* rhs);
  friend bool operator==(const stringx& lhs, const char *rhs);

  char *chars;
  string_buf *my_buf;

public:
  stringx();
  stringx(const stringx &cp);
  ~stringx();
  stringx &operator=(const stringx &cp);
  void make_room(int size);
  void append(const char *str, int len = -1);
  void append(const stringx &cp);
};

inline bool operator==(const stringx& lhs, const char *rhs)
{
  return lhs.my_buf->is_equal(rhs);
}

inline stringx operator+(const stringx& lhs, const char* rhs)
{
  stringx foo;
  int len = strlen(rhs);

  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);

  return foo;
}

void warning(const stringx& str);

class os_developer_options
{
  char base[4];
  bool flags[125];
  static os_developer_options *instance;

public:
  enum flags_t
  {
    FLAG_NO_CD = 4,
    FLAG_MOVE_EDITOR = 124
  };

  static os_developer_options *inst()
  {
    return instance;
  }

  bool is_flagged(flags_t _flag) const { return flags[_flag]; }
};

class os_file
{
public:
  enum mode_flags
  {
    FILE_READ = 1
  };

  void open(const stringx & _name, int _flags);
  static bool is_system_locked() { return system_locked; }

private:
  stringx name;
  int flags;
  bool opened;
  bool eof;
  bool from_cd;

  static bool system_locked;

  bool try_to_open_from_cd();
  bool try_to_open_from_disk();
};

#define assert(exp) ((void)0)

static inline void check_system_locked( const stringx& name )
{
  if ( os_file::is_system_locked()  && !os_developer_options::inst()->is_flagged(os_developer_options::FLAG_MOVE_EDITOR))
    warning( name + ": os_file system is locked; no file access allowed" );
}

void os_file::open(const stringx & _name, int _flags)
{
  bool ret = false;
  assert(!opened);

  check_system_locked( _name );

  name = _name;
  flags = _flags;

  if (( _flags & FILE_READ) &&
    (_name == "GAME.INI" ||	// next line will crash unless game.ini already loaded (dc 01/07/02)
    !os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_CD)))
  {
    ret = try_to_open_from_cd();
    if( ret ) return;
  }

  if (ret == false)
  {
    ret = try_to_open_from_disk();
  }

  if (ret == false)
  {
//    let's fail silently
//    nglPrintf("Error.  Could not open file %s on either the cd or the host disk.\n", name.c_str());
    opened = false;
  }
}
